const message = $json;
const headers = Array.isArray(message.payload?.headers) ? message.payload.headers : [];
const header = (name) => headers.find(h => String(h.name).toLowerCase() === name.toLowerCase())?.value;
const from = header('From') ?? message.from ?? '';
const match = String(from).match(/^(?:(.*?)\s*)?<([^>]+)>$/);
const address = (match?.[2] ?? from).trim().toLowerCase();
const name = match?.[1]?.replace(/^"|"$/g, '').trim() || undefined;
const occurredAt = message.internalDate ? new Date(Number(message.internalDate)).toISOString() : new Date().toISOString();
const eventId = crypto.randomUUID();
return [{ json: { schemaVersion: 1, eventId, tenantId: $env.LOCAL_TENANT_ID, source: 'gmail', externalId: String(message.id), occurredAt, receivedAt: new Date().toISOString(), sender: { address, ...(name ? { name } : {}), ...(address.includes('@') ? { domain: address.split('@').pop() } : {}) }, ...(header('Subject') ? { subject: header('Subject') } : {}), ...(message.text ? { textBody: message.text } : {}), ...(message.html ? { htmlBody: message.html } : {}), labels: message.labelIds ?? [], attachments: [], metadata: { gmailThreadId: message.threadId, connector: 'gmail-trigger', classificationLabels: [] } } }];

const e = $json;
const required = ['schemaVersion','eventId','tenantId','source','externalId','occurredAt','receivedAt','sender'];
for (const key of required) if (e[key] === undefined || e[key] === null || e[key] === '') throw new Error('Invalid EmailSourceEvent: missing ' + key);
if (e.schemaVersion !== 1 || e.source !== 'gmail') throw new Error('Unsupported EmailSourceEvent version or source');
if (!e.sender?.address || !String(e.sender.address).includes('@')) throw new Error('Invalid sender address');
return items;

const response = $json;
if (response.statusCode && response.statusCode >= 400 && response.statusCode !== 409) throw new Error('Source event ingestion failed with HTTP ' + response.statusCode);
const event = $('Validate EmailSourceEvent').item.json;
return [{ json: { ...event, ingestionDuplicate: Boolean(response.body?.duplicate) } }];
